{
  "id": 37,
  "knowledge": "Physical Endurance Rating (PER)",
  "description": "Measures the physical endurance of a device under intense gaming conditions, combining durability with effective heat management. ",
  "definition": "PER = DS \\times \\left(1 + \\frac{DustRes score + WaterRes score}{6}\\right) \\times \\left(1 - \\frac{100 - BendForce}{200}\\right), where DustRes and WaterRes are scored based on IP ratings (IPX0=0, IPX1=1, IPX2=2, IPX3=3)."
}

{
  "id": 47,
  "knowledge": "Ultra-Durable Tournament Device",
  "description": "Defines devices with exceptional physical durability designed to withstand the rigors of frequent tournament travel and intensive competition use.",
  "definition": "A device with PER > 9.0, DS > 8.5, UsbConnDur > 20000, and at least one premium durability feature (DropHtM > 2.0 or WaterRes containing 'IPX7' or higher), engineered to maintain performance integrity despite frequent transportation, setup/teardown cycles, and competition intensity."
}

{
  "id": 16,
  "knowledge": "Competitive-Grade Durability",
  "description": "Defines durability standards for devices intended for intensive competitive use.",
  "definition": "A device with DS > 8.5, UsbConnDur > 15000, DropHtM > 1.5, and GripDur > 1000, designed to withstand the rigors of frequent transport and intensive use during tournament environments."
}

